-- database/schema.sql — v1 FOUNDATION ONLY (DBA owns everything past here).
-- Skeleton ships the two tables auth needs to boot. Listings, farms, categories,
-- orders, messages: design + add via migrations/001_xxx.sql etc. Do NOT edit this file
-- after Sprint 1 — add new tables in numbered migration files instead.

CREATE TABLE IF NOT EXISTS roles (
    id   INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    slug VARCHAR(32) NOT NULL UNIQUE COMMENT 'buyer | farmer | admin',
    name VARCHAR(64) NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS users (
    id            INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    role_id       INT UNSIGNED NOT NULL,
    name          VARCHAR(120) NOT NULL,
    email         VARCHAR(190) NOT NULL UNIQUE,
    password_hash VARCHAR(255) NOT NULL,
    created_at    TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT fk_users_role FOREIGN KEY (role_id) REFERENCES roles (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE INDEX idx_users_email ON users (email);

